set -euo pipefail
docker exec -i deploy-gaybbs-1 node --import /app/preload/telegram-ipv4-preload.mjs - <<'JS' | gh issue comment 4 --repo seigo-gace/GateApp-Bot --body-file - >/dev/null
const fs=require("fs");
const token=fs.readFileSync("/run/secrets/bot_token","utf8").trim();
const targets=[["area_bbs",-1003847210571,48],["video_chat",-1002373696859,1613],["gay_board",-1003770334893,210]];
async function call(method,data){const r=await fetch("https://api.telegram.org/bot"+token+"/"+method,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(data)});const j=await r.json();if(!j.ok)throw Error(method+":"+String(j.description).slice(0,100));return j.result}
(async()=>{
 console.log("PR47_THREE_TOPIC_SEND_DELETE_SMOKE");
 let failed=false;
 for(const [board,chat,thread] of targets){
  let id=null;
  try{
   const p=await call("sendMessage",{chat_id:chat,message_thread_id:thread,text:"🧪 プロフィール掲載テスト（自動削除）",disable_notification:true});
   id=p.message_id;
   if(p.message_thread_id!==thread)throw Error("WRONG_THREAD");
   const deleted=await call("deleteMessage",{chat_id:chat,message_id:id});
   if(deleted!==true)throw Error("DELETE_FAILED");
   console.log("TOPIC="+board+":"+thread+"|SEND=PASS|DELETE=PASS");
  }catch(e){
   failed=true;console.log("TOPIC="+board+":"+thread+"|SMOKE=FAIL|CAUSE="+String(e.message).replace(/[\r\n]/g," ").slice(0,130));
   if(id!==null){try{await call("deleteMessage",{chat_id:chat,message_id:id});console.log("CLEANUP=PASS")}catch{console.log("CLEANUP=NOT_VERIFIED")}}
  }
 }
 console.log("THREE_TOPIC_SMOKE="+(failed?"FAIL":"PASS"));
 if(failed)process.exitCode=81;
})().catch(e=>{console.log("TOPIC_SMOKE_RUNTIME_ERROR="+String(e.message).slice(0,100));process.exitCode=82});
